The approach is a greedy heuristic with a local-search-free ordering.

1. Score each library as (sum of the values of its not-yet-scanned books that fit in the remaining time) / signup time. Only the top `(D - t - T) * M` books count, where t is the current time and T the signup time.
2. Computing this exactly for every library at every step is too slow. Instead I use a lazy priority queue (lazy greedy): each library's score is cached, and when the best entry is popped it is recomputed with the current state. If it is still at least as good as the next entry in the queue, it is chosen; otherwise it is pushed back with the new value. Scores only decrease as books get used and time advances, so this is sound enough as a heuristic.
3. Recomputing a library's score means scanning its books, which costs O(N log N) if sorted. To avoid re-sorting, each library's books are pre-sorted once by score descending. A recompute then walks the list, skips books already used, and takes up to `cap = (D - t - T) * M` of them. Each walk is O(N) in the worst case. The total number of recomputes is bounded by the lazy mechanism, and I accept the risk.
4. When a library is chosen, it takes the first `cap` unused books in its sorted order. I mark those books used, set t += T, and output the library. If cap <= 0 the library is skipped (its score is 0).
5. Libraries with a non-positive remaining time are dropped. Libraries with a score of 0 or with no books picked are not output, because K must be at least 1.

The score key is value / T as a double. Ties are broken by library index so the output is deterministic.

To bound the runtime, the walk in the recompute stops after collecting `cap` books. Skipped used books still cost time, but the total is acceptable in practice.

Output is buffered into a string. Input is read with a fast reader.

```cpp
#include <bits/stdc++.h>
using namespace std;
int main(){
    int B,L,D;
    if(scanf("%d %d %d",&B,&L,&D)!=3) return 0;
    vector<int> S(B);
    for(auto&x:S) scanf("%d",&x);
    vector<vector<int>> bk(L);
    vector<int> T(L),M(L);
    for(int j=0;j<L;j++){
        int n;
        scanf("%d %d %d",&n,&T[j],&M[j]);
        bk[j].resize(n);
        for(auto&x:bk[j]) scanf("%d",&x);
        sort(bk[j].begin(),bk[j].end(),[&](int a,int b){
            if(S[a]!=S[b]) return S[a]>S[b];
            return a<b;
        });
    }
    vector<char> used(B,0);
    long long t=0;
    auto eval=[&](int j)->double{
        long long rem=D-t-T[j];
        if(rem<=0) return 0;
        long long cap=rem*(long long)M[j];
        long long cnt=0,val=0;
        for(int b:bk[j]){
            if(used[b]) continue;
            val+=S[b];
            if(++cnt>=cap) break;
        }
        return (double)val/T[j];
    };
    priority_queue<pair<double,int>> pq;
    for(int j=0;j<L;j++){
        double v=eval(j);
        if(v>0) pq.push({v,-j});
    }
    vector<pair<int,vector<int>>> res;
    while(!pq.empty()){
        auto [v,nj]=pq.top();pq.pop();
        int j=-nj;
        double nv=eval(j);
        if(nv<=0) continue;
        if(!pq.empty()){
            auto tp=pq.top();
            if(nv<tp.first || (nv==tp.first && -j>tp.second)){
                pq.push({nv,-j});
                continue;
            }
        }
        long long rem=D-t-T[j];
        long long cap=rem*(long long)M[j];
        vector<int> pick;
        for(int b:bk[j]){
            if(used[b]) continue;
            pick.push_back(b);
            used[b]=1;
            if((long long)pick.size()>=cap) break;
        }
        if(pick.empty()) continue;
        t+=T[j];
        res.push_back({j,pick});
    }
    string out=to_string(res.size())+"\n";
    for(auto&r:res){
        out+=to_string(r.first)+" "+to_string(r.second.size())+"\n";
        for(size_t i=0;i<r.second.size();i++){
            if(i) out+=' ';
            out+=to_string(r.second[i]);
        }
        out+='\n';
    }
    fputs(out.c_str(),stdout);
}
